"""Self-contained interactive HTML explorer of saved CSVs; no live inference."""
from pathlib import Path
import csv,json
ROOT=Path(__file__).resolve().parent

def main():
    read=lambda name:list(csv.DictReader((ROOT/'outputs'/name).read_text().splitlines()))
    fields=['case','secondary_dt','condition','B_TBR','inventory_change_kg','B_burn_kg','unserved_burn_kg','mass_residual_kg']
    integrated=[{k:r[k] for k in fields} for r in read('integrated_cases.csv')]
    transport=[{k:r[k] for k in ['case_id','source','li6','blanket_cm','T_per_source_neutron','T_se_bound','leakage']} for r in read('transport_summary.csv')]
    curves={name:[{k:float(r[k]) for k in ['day','total_inventory','b_store']} for r in read(name+'_daily.csv')] for name in ['A0','A1','A2_grid_candidate']}
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Beyond Q v1.2 research explorer</title>
<style>body{font:16px system-ui,sans-serif;background:#edf2f5;color:#172b3a;margin:0}main{max-width:1100px;margin:auto;padding:28px}h1{font-size:30px;margin-bottom:8px}h2{font-size:21px}.notice{background:#fff0ce;border-left:5px solid #a96900;padding:16px;line-height:1.5}section{background:white;border-radius:10px;padding:22px;margin:22px 0}label{display:inline-block;margin:8px 16px 8px 0}select{padding:8px;border:1px solid #899aa5;border-radius:4px;font-size:15px}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:9px;border-bottom:1px solid #ddd}svg{width:100%;height:auto}.scroll{overflow:auto}.metrics{display:flex;flex-wrap:wrap;gap:16px}.metric{background:#edf3f7;padding:15px;min-width:155px}.metric strong{display:block;font-size:24px}small{color:#526575}a{color:#155979}</style>
<main><h1>Beyond Q · v1.2</h1><p>Source-resolved neutronics and dynamic fuel-cycle research · October 30, 2026</p>
<div class="notice"><b>Research scenario explorer — no operational self-sufficiency established.</b><br>B: 1.13 GW D-T. A: hypothetical 20 MW primary D-D. Actual OpenMC calculations use an assumed spherical geometry and 293.6 K nuclear data. All physical gates G1–G5 remain OPEN. Qualified usable surplus is unresolved.</div>
<section><h2>Conditional 365-day fuel-cycle cases</h2><p>Filter recorded scenarios. Positive final stock growth does not imply uninterrupted fuel supply.</p><label>A case <select id="acase"></select></label><label>Condition <select id="condition"></select></label><label>Secondary D-T <select id="secondary"><option value="True">On</option><option value="False">Off</option></select></label><div class="metrics" id="metrics"></div><p><small>Stock growth includes all modeled mobile compartments. Initial B stock is 10 kg, except cold-start cases. Nuclear sources are limited by actual fuel availability. No purity-qualified export is calculated.</small></p></section>
<section><h2>Reference inventory trajectories</h2><p>Full scheduled uptime, secondary D-T on. These curves do not change with the adverse-condition filter above.</p><label>Inventory <select id="stock"><option value="total_inventory">All mobile stocks</option><option value="b_store">B available storage</option></select></label><svg id="chart" viewBox="0 0 900 330" role="img" aria-label="Conditional inventory trajectories"></svg><p><small>Blue: A0 · teal: A1 · purple: A2 grid candidate. Splitting timestep 0.125 day; reference A1 refinement changes final stock by approximately 10 grams. These are modeled stocks, not measured reserves.</small></p></section>
<section><h2>44 actual transport calculations</h2><label>Source <select id="source"><option value="all">All</option><option>DD</option><option>DT</option></select></label><p>Yield = salt tritium atoms per source neutron. SE is a conservative sum of marginal standard errors; physical uncertainty is unquantified.</p><div class="scroll"><table><thead><tr><th>Case</th><th>Li-6 fraction</th><th>Blanket cm</th><th>Salt yield</th><th>SE bound</th><th>Leakage / source</th></tr></thead><tbody id="transport"></tbody></table></div></section>
<p>Read WHITE_PAPER.md, SOURCES.md, gate_status.json and the CSVs beside this file. A2 is a finite-grid candidate, not an engineering optimum. Zero observed leakage is a nondetection, not a zero-dose guarantee. No external JavaScript or network requests.</p></main>
<script>const cases=__CASES__,runs=__RUNS__,curves=__CURVES__;
const el=id=>document.getElementById(id),fmt=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:6});
for(const [id,key] of [['acase','case'],['condition','condition']]){for(const x of [...new Set(cases.map(r=>r[key]))]){let o=document.createElement('option');o.value=x;o.textContent=x;el(id).append(o)}}
function update(){let r=cases.find(r=>r.case===el('acase').value&&r.condition===el('condition').value&&r.secondary_dt===el('secondary').value);el('metrics').replaceChildren();for(let [title,value,unit] of [['Stock growth',r.inventory_change_kg,'kg-T'],['Unserved B burn',r.unserved_burn_kg,'kg-T'],['B actual burn',r.B_burn_kg,'kg-T'],['Mass residual',r.mass_residual_kg,'kg-T']]){let box=document.createElement('div');box.className='metric';let name=document.createElement('span');name.textContent=title;let number=document.createElement('strong');number.textContent=title==='Mass residual'?Number(value).toExponential(2):fmt(value);let suffix=document.createElement('small');suffix.textContent=unit;box.append(name,number,suffix);el('metrics').append(box)}}
function chart(){let key=el('stock').value,all=Object.values(curves).flat().map(x=>x[key]),lo=Math.min(0,...all),hi=Math.max(...all)*1.08;let X=x=>60+x/365*810,Y=y=>280-(y-lo)/(hi-lo)*250;let svg='<line x1="60" y1="280" x2="870" y2="280" stroke="#777"/><text x="430" y="320" font-size="14">Calendar day</text><text x="8" y="20" font-size="14">kg-T</text>';for(let i=0;i<=4;i++){let v=lo+(hi-lo)*i/4;svg+=`<line x1="60" x2="870" y1="${Y(v)}" y2="${Y(v)}" stroke="#e0e6eb"/><text x="10" y="${Y(v)+5}" font-size="12">${v.toFixed(1)}</text>`}for(let d of [0,100,200,300,365])svg+=`<text x="${X(d)-8}" y="300" font-size="12">${d}</text>`;Object.entries(curves).forEach(([name,rows],i)=>{let points=rows.map(r=>`${X(r.day)},${Y(r[key])}`).join(' ');svg+=`<polyline points="${points}" fill="none" stroke="${['#2668a6','#008b80','#7954aa'][i]}" stroke-width="2.5"/>`});el('chart').innerHTML=svg}
function transport(){el('transport').replaceChildren();for(let r of runs.filter(r=>el('source').value==='all'||r.source===el('source').value)){let tr=document.createElement('tr');for(let k of ['case_id','li6','blanket_cm','T_per_source_neutron','T_se_bound','leakage']){let td=document.createElement('td');td.textContent=k==='case_id'?r[k]:fmt(r[k]);tr.append(td)}el('transport').append(tr)}}
for(let id of ['acase','condition','secondary'])el(id).addEventListener('change',update);el('stock').addEventListener('change',chart);el('source').addEventListener('change',transport);update();chart();transport();</script></html>'''
    for key,value in [('__CASES__',integrated),('__RUNS__',transport),('__CURVES__',curves)]:template=template.replace(key,json.dumps(value,separators=(',',':')))
    (ROOT/'dashboard.html').write_text(template)
if __name__=='__main__':main()
